<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $members = $args['members']; ?><div class="sd-member-list"><?php foreach ( $members as $member ) : ?><article class="sd-member-list-item"><img src="<?php echo esc_url( sd_avatar( $member->ID, 64 ) ); ?>" alt="" width="64" height="64"><div><h3><a href="<?php echo esc_url( sd_get_member_url( $member->ID ) ); ?>"><?php echo esc_html( sd_member_display_name( $member->ID ) ); ?></a></h3><p><?php echo esc_html( wp_trim_words( $member->description, 22 ) ); ?></p></div><?php get_template_part( 'template-parts/discovery/connection-button', null, array( 'member_id' => $member->ID ) ); ?></article><?php endforeach; ?></div>
